import {requireVendorMember} from '@/lib/vendors';
import {prisma} from '@/lib/prisma';
import {saveVendorProduct} from '@/app/vendor/actions';
export default async function NewVendorProduct({searchParams}:{searchParams:Promise<{vendorId?:string}>}){const p=await searchParams;const {vendor}=await requireVendorMember(p.vendorId);const categories=await prisma.category.findMany({orderBy:{name:'asc'}});return <main className="admin-content"><p className="eyebrow">VENDOR PRODUCT</p><h1 className="admin-title">Submit a product</h1><form action={saveVendorProduct} encType="multipart/form-data" className="admin-panel mt-8 max-w-2xl space-y-4"><input type="hidden" name="vendorId" value={vendor.id}/><label>Name<input className="form-input" name="name" required/></label><label>Slug<input className="form-input" name="slug" required/></label><label>Description<textarea className="form-input min-h-32" name="description" required/></label><label>Category<select className="form-input" name="categoryId" required>{categories.map(c=><option key={c.id} value={c.id}>{c.name}</option>)}</select></label><label>Price MMK<input className="form-input" type="number" name="priceMmk" min="0" required/></label><label>Technology<input className="form-input" name="technology" placeholder="Next.js, TypeScript"/></label><label>Demo URL<input className="form-input" name="demoUrl" type="url"/></label><label>Private source ZIP<input className="form-input" name="sourceFile" type="file" accept=".zip,application/zip"/></label><button className="btn-primary">Submit for moderation</button></form></main>}
